// Isomorphic: the cloud backend runs prepareGeneration and the adapters in the browser.
import data from "./generated/catalog.json";
import { modelMeta } from "./meta";
import type { Catalog, CatalogModel, CatalogSummary } from "./types";

/** The single model registry. Generated by scripts/build-catalog.ts — do not edit the JSON. */
export const catalog = data as unknown as Catalog;

const byKey = new Map(catalog.models.map((m) => [m.key, m]));

export function getModel(key: string): CatalogModel | undefined {
  return byKey.get(key);
}

export function listSummaries(): CatalogSummary[] {
  return catalog.models.map((m) => ({
    key: m.key,
    modelId: m.modelId,
    title: m.title,
    provider: m.provider,
    family: m.family,
    category: m.category,
    operation: m.operation,
    issues: m.issues,
    free: m.free,
    promptReferenceSyntax: m.promptReferenceSyntax,
    // Read-only facts for picker cards (price range, duration, audio, reference kinds).
    meta: modelMeta(m),
  }));
}
